import type { Invitation } from "../data/schema";

/**
 * Contract every scene follows:
 * - Renders a complete, self-lit 1080×1920 frame (own background, lighting, optional frame).
 * - Frame 0 already shows the established background; elements then reveal in stages.
 * - The first ~24 and last ~30 frames overlap a transition, so key action sits in the middle
 *   and the scene HOLDS (no exits) at the end.
 * - All text comes from `inv` (never hard-code names, dates, venues).
 */
export type SceneProps = {
  inv: Invitation;
  /** Scene length in frames (30 fps). */
  dur: number;
  /** True when the scene is the single event of a short version (it gets more time). */
  solo?: boolean;
  /** Frames to add to the local frame so multiples of 18 land on the music's beats. */
  beatOffset?: number;
};
